// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer calls XBornID() to set initial state
        c.XBornID();

        // Get a non-blacklisted user (deployer itself is not blacklisted initially)
        address user = address(this);

        // Attempt to call getTokens() - in reference it should succeed, in bug it should revert
        try c.getTokens() {
            // If call succeeds, check that value is now 1000e18 / 100000 * 99999 = 99999e17 (approx)
            // Actually check that totalRemaining decreased (distr happened)
            assertTrue(c.totalDistributed() > 200000000e18, "Distribution should have increased");
        } catch {
            // If it reverts, we fail the test (buggy version would revert)
            assertTrue(false, "getTokens() reverted - bug detected");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call XBornID() to initialize balances
        c.XBornID();
        // After XBornID(), value = 1000e18 = 1000000000000000000000
        // In reference: value = (1000e18 / 100000) * 99999 = (10^19? Actually 1000*10^18 = 10^21 / 10^5 = 10^16) * 99999 = 10^16 * 99999 = 999990000000000000000000? Let's compute correctly:
        // 1000e18 = 1000000000000000000000
        // / 100000 = 10000000000000000 (10^16)
        // * 99999 = 999990000000000000000 (approx 99999e16)
        // For the reference, after first getTokens call, value becomes 99999e16 = 999990000000000000000 (less than 1000e18)
        // For the bug: /1000 = 1000000000000000000 (10^18) * 99999 = 99999000000000000000000 (still huge)
        // Better to call getTokens first to see difference clearly:
        // Actually we need a scenario where value becomes 0 in reference but not in bug.
        // Let's use deal and a prank to call getTokens repeatedly.
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.getTokens();
        // After one call, value in reference: 1000e18 / 100000 * 99999 = 999990000000000000000 (non-zero)
        // To get to zero, many calls needed. Let's compute:
        // reference value sequence: v0 = 1000e18
        // v1 = v0/100000 * 99999 = 99999e16 = 999990000000000000000
        // v2 = v1/100000 * 99999 = floor(999990000000000000000/100000)=9999900000000000 * 99999 = 999980000100000000000? Actually:
        // v1/100000 = 9999900000000 (13 digits? 999990000000000000000/100000 = 9999900000000000? Let's do: 999,990,000,000,000,000,000 / 100,000 = 9,999,900,000,000,000? No, 999990000000000000000 / 100000 = 9999900000000000? That's wrong: dividing a number ending with '000' by 100000 = remove 5 zeros: 9999900000000000 -> but original had 18 zeros? Simpler: 
        // Actually for reference to reach 0, we need the division to become less than 100000 so that value/100000 = 0, then *99999 = 0.
        // The bug divides by 1000, so value/1000 becomes 0 only when value < 1000, much later.
        // This contrast is clear: when value is small enough (1 to 999), reference gives 0, bug gives non-zero.
        // So after many calls, value will get small. Let's simulate to find a state:
        // We'll call getTokens repeatedly until reference would make value=0 but bug wouldn't.
        // Hard-code enough calls: approximately 10-15 calls.
        for (uint i = 0; i < 15; i++) {
            vm.deal(address(uint160(i+2)), 1 ether);
            vm.prank(address(uint160(i+2)));
            c.getTokens();
        }
        // Now check value:
        uint256 val = c.value();
        // Reference would have value = 0 because division truncation eventually zeroes out
        // Bug would have non-zero because dividing by 1000 preserves more
        assertTrue(val == 0, "value should be 0 in reference, but bug gives non-zero");
    }
}

